-- Candidate: retain the REVIEW claim until unique-preimage cleanup readback.
DROP TRIGGER IF EXISTS continuous_final_notice_cleanup_insert;
CREATE TRIGGER IF NOT EXISTS continuous_final_notice_cleanup_insert BEFORE INSERT ON continuous_final_notice_cleanup
WHEN NOT EXISTS(SELECT 1 FROM continuous_review_notice_close n JOIN stable_workbook_claims c ON c.spreadsheet_id=n.spreadsheet_id AND c.operation_token=n.operation_token JOIN stable_recovery_epochs e ON e.epoch_id=n.epoch_id AND e.spreadsheet_id=n.spreadsheet_id JOIN stable_recovery_operations o ON o.epoch_id=e.epoch_id AND o.operation_token=n.operation_token JOIN sync_jobs j ON j.entity_type='EXPENSE' AND j.entity_key=n.expense_id AND j.entity_version=n.source_version WHERE n.operation_token=NEW.operation_token AND n.spreadsheet_id=NEW.spreadsheet_id AND n.projection='FINAL' AND n.claim_mode='HANDOFF' AND n.state='FINAL_COMMITTED' AND n.ready_status=NEW.find_status AND n.next_stamp=NEW.notice_stamp AND c.state='HELD' AND c.phase='END_NOTICE_PENDING' AND c.notice_identity=n.notice_identity AND c.notice_stamp=n.next_stamp AND e.state='COMPLETE' AND e.target_type='EXPENSE' AND e.target_key=n.expense_id AND e.target_version=n.source_version AND o.state='VERIFIED' AND j.status='COMPLETED' AND ((NEW.replacement_status='พร้อมแก้ไข' AND NOT EXISTS(SELECT 1 FROM sync_jobs WHERE status='REVIEW')) OR (NEW.replacement_status='พร้อมแก้ไข • มีรายการรอตรวจ' AND EXISTS(SELECT 1 FROM sync_jobs WHERE status='REVIEW')))) AND NOT EXISTS(SELECT 1 FROM continuous_review_notice_close n JOIN stable_workbook_claims c ON c.spreadsheet_id=n.spreadsheet_id AND c.operation_token=n.operation_token JOIN stable_recovery_epochs e ON e.epoch_id=n.epoch_id AND e.spreadsheet_id=n.spreadsheet_id JOIN stable_recovery_operations o ON o.epoch_id=e.epoch_id AND o.operation_token=n.operation_token JOIN sync_jobs j ON j.entity_type='EXPENSE' AND j.entity_key=n.expense_id AND j.entity_version=n.source_version JOIN continuous_revoke_review_close_activation a ON a.singleton=1 WHERE n.operation_token=NEW.operation_token AND n.spreadsheet_id=NEW.spreadsheet_id AND n.projection='PUBLICATION' AND n.operation_kind='CANCEL' AND n.claim_mode='REVIEW' AND n.state='FINAL_COMMITTED' AND n.ready_status=NEW.find_status AND n.next_stamp=NEW.notice_stamp AND c.state='REVIEW' AND c.phase='OPERATION' AND c.notice_identity=n.notice_identity AND c.notice_stamp=n.next_stamp AND e.state='ARMED' AND e.target_type='EXPENSE' AND e.target_key=n.expense_id AND e.target_version=n.source_version AND o.state='VERIFIED' AND j.status='PENDING' AND j.lease_token IS NULL AND j.lease_until IS NULL AND ((NEW.replacement_status='พร้อมแก้ไข' AND NOT EXISTS(SELECT 1 FROM sync_jobs WHERE status='REVIEW')) OR (NEW.replacement_status='พร้อมแก้ไข • มีรายการรอตรวจ' AND EXISTS(SELECT 1 FROM sync_jobs WHERE status='REVIEW'))))
BEGIN SELECT RAISE(ABORT,'final cleanup requires committed exact target'); END;

DROP TRIGGER IF EXISTS continuous_notice_status_attempt_insert;
CREATE TRIGGER IF NOT EXISTS continuous_notice_status_attempt_insert BEFORE INSERT ON continuous_notice_status_attempts
WHEN NOT EXISTS(SELECT 1 FROM continuous_review_notice_close n JOIN stable_workbook_claims c ON c.spreadsheet_id=n.spreadsheet_id AND c.operation_token=n.operation_token JOIN stable_source_revision r ON r.singleton=1 WHERE n.operation_token=NEW.operation_token AND n.spreadsheet_id=NEW.spreadsheet_id AND n.state='TIME_VERIFIED' AND n.ready_status=NEW.initial_ready_status AND n.next_stamp=NEW.next_stamp AND c.notice_stamp=n.next_stamp AND c.notice_identity=n.notice_identity AND r.revision=NEW.source_revision AND (((NEW.dispatch_ready_status IN ('พร้อมแก้ไข','พร้อมแก้ไข • กำลังซิงก์') OR NEW.dispatch_ready_status GLOB 'พร้อมแก้ไข • กำลังซิงก์ • รหัส *') AND NOT EXISTS(SELECT 1 FROM sync_jobs WHERE status='REVIEW')) OR ((NEW.dispatch_ready_status IN ('พร้อมแก้ไข • มีรายการรอตรวจ','พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ') OR NEW.dispatch_ready_status GLOB 'พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ • รหัส *') AND EXISTS(SELECT 1 FROM sync_jobs WHERE status='REVIEW'))) AND ((n.claim_mode='REVIEW' AND c.state='REVIEW' AND c.phase='OPERATION' AND (NEW.dispatch_ready_status IN ('พร้อมแก้ไข','พร้อมแก้ไข • มีรายการรอตรวจ') OR (n.projection='PUBLICATION' AND n.operation_kind='CANCEL' AND EXISTS(SELECT 1 FROM continuous_revoke_review_close_activation a WHERE a.singleton=1) AND NEW.dispatch_ready_status='พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ • รหัส '||substr(n.next_stamp,-32)))) OR (n.claim_mode='HANDOFF' AND c.state='HELD' AND c.phase='END_NOTICE_PENDING' AND (NEW.dispatch_ready_status IN ('พร้อมแก้ไข • กำลังซิงก์','พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ') OR NEW.dispatch_ready_status GLOB 'พร้อมแก้ไข • กำลังซิงก์ • รหัส *' OR NEW.dispatch_ready_status GLOB 'พร้อมแก้ไข • กำลังซิงก์ • มีรายการรอตรวจ • รหัส *'))))
BEGIN SELECT RAISE(ABORT,'status attempt requires verified notice and current review state'); END;
